  "admin.icpTextPlaceholder": { "zh-CN": "如 京ICP备12345678号-1 / 萌ICP备20260645号，留空不显示", "zh-TW": "如 京ICP備12345678號-1 / 萌ICP備20260645號，留空不顯示", en: "e.g. 京ICP备12345678号-1 / 萌ICP备20260645号, leave blank to hide", fr: "ex. 京ICP备12345678号-1 / 萌ICP备20260645号, laisser vide pour masquer" },
  "admin.icpPasteHint": { "zh-CN": "可直接粘贴第三方备案给的整段 <a> 标签，会自动拆出链接与文字。", "zh-TW": "可直接貼上第三方備案給的整段 <a> 標籤，會自動拆出連結與文字。", en: "You can paste the whole <a> tag from a third-party registry; the link and text are split automatically.", fr: "Vous pouvez coller toute la balise <a> d'un registre tiers ; le lien et le texte sont séparés automatiquement." },
